def batch_status(state_path: Path) -> dict[str, Any]:
    state_path = state_path.expanduser().resolve()
    state = _load_state(state_path)
    plan = _load_batch_plan(Path(state["plan"]))
    plan_by_id = {item["project_id"]: item for item in plan["projects"]}
    projects = []
    drifted = 0
    for project_id in sorted(state["projects"]):
        item = dict(state["projects"][project_id])
        plan_project = plan_by_id[project_id]
        current_digest = None
        expected_digest = None
        if plan_project["status"] == "ready":
            current_digest = snapshot_digest(
                snapshot_files(
                    Path(plan_project["output"]),
                    [Path(value) for value in plan_project["workspace_roots"]],
                )
            )
            expected_digest = item["baseline_digest"] if item["status"] == "rolled-back" else item["applied_digest"]
            if expected_digest and current_digest != expected_digest:
                item["drift"] = {"category": "managed-bytes-drift", "expected": expected_digest, "actual": current_digest}
                drifted += 1
            else:
                item["drift"] = None
        item["current_digest"] = current_digest
        item["recovery"] = f"agent-policy batch rollback --state '{state_path}' --project {project_id}"
        projects.append(item)
    counts: dict[str, int] = {}
    for item in projects:
        counts[item["status"]] = counts.get(item["status"], 0) + 1
    status = "drifted" if drifted else state["status"]
    return {
        "schema_version": BATCH_STATE_SCHEMA_VERSION,
        "batch_id": state["batch_id"],
        "status": status,
        "state": str(state_path),
        "plan": state["plan"],
        "summary": {"projects": len(projects), "drifted": drifted, "counts": dict(sorted(counts.items()))},
        "projects": projects,
        "event_count": len(state.get("events", [])),
    }

def audit_batch_state(state_path: Path) -> dict[str, Any]:
    state_path = state_path.expanduser().resolve()
    state = _load_state(state_path)
    plan = _load_batch_plan(Path(state["plan"]))
    plan_by_id = {item["project_id"]: item for item in plan["projects"]}
    results = []
    for project_id in sorted(state["projects"]):
        project_state = state["projects"][project_id]
        project = plan_by_id[project_id]
        errors = []
        audit = None
        if project["status"] != "ready":
            errors.append({"category": "plan-project-failed"})
        elif project_state["status"] in {"completed", "skipped"}:
            from .agent_protocol import audit_agent_protocol

            audit = audit_agent_protocol(Path(project["output"]))
            if audit.get("status") != "passed":
                errors.append({"category": "agent-policy-audit-failed", "evidence": str(Path(project["output"]) / "workspace-meta/agent-protocol-audit.json")})
            current = snapshot_digest(
                snapshot_files(Path(project["output"]), [Path(value) for value in project["workspace_roots"]])
            )
            if current != project_state["applied_digest"]:
                errors.append({"category": "applied-bytes-drift", "expected": project_state["applied_digest"], "actual": current})
            evidence = project_state.get("evidence")
            if not evidence or not Path(evidence).is_file():
                errors.append({"category": "batch-evidence-missing"})
        elif project_state["status"] == "rolled-back":
            current = snapshot_digest(
                snapshot_files(Path(project["output"]), [Path(value) for value in project["workspace_roots"]])
            )
            if current != project_state["baseline_digest"]:
                errors.append({"category": "rollback-bytes-drift", "expected": project_state["baseline_digest"], "actual": current})
        else:
            errors.append({"category": "project-not-complete", "status": project_state["status"]})
        result = {
            "project_id": project_id,
            "status": "passed" if not errors else "failed",
            "source_version": project_state["source_version"],
            "target_version": project_state["target_version"],
            "evidence": project_state.get("evidence"),
            "recovery": f"agent-policy batch rollback --state '{state_path}' --project {project_id}",
            "agent_policy": audit,
            "errors": errors,
        }
        results.append(result)
        if project["status"] == "ready" and Path(project["output"]).is_dir():
            evidence = _write_project_evidence(Path(project["output"]), state["batch_id"], project_state, "audit")
            project_state["evidence"] = str(evidence)
            _journal_batch_result(Path(project["output"]), "audit", result["status"], evidence)
    failed = sum(item["status"] == "failed" for item in results)
    _append_state_event(state, "batch", "audit", "passed" if failed == 0 else "failed", None if failed == 0 else "project-audit-failed")
    _save_state(state_path, state)
    return {
        "schema_version": BATCH_STATE_SCHEMA_VERSION,
        "batch_id": state["batch_id"],
        "status": "passed" if failed == 0 else "failed",
        "state": str(state_path),
        "summary": {"projects": len(results), "passed": len(results) - failed, "failed": failed},
        "projects": results,
    }

def rollback_batch_state(state_path: Path, project_ids: list[str] | None = None) -> dict[str, Any]:
    state_path = state_path.expanduser().resolve()
    state = _load_state(state_path)
    plan = _load_batch_plan(Path(state["plan"]))
    plan_by_id = {item["project_id"]: item for item in plan["projects"]}
    requested = sorted(set(project_ids or []))
    unknown = sorted(set(requested) - set(state["projects"]))
    if unknown:
        raise CkbError(f"unknown Agent Protocol batch rollback project: {', '.join(unknown)}")
    selected = requested or sorted(
        project_id
        for project_id, item in state["projects"].items()
        if item["status"] in {"completed", "skipped"}
    )
    if not selected:
        raise CkbError("Agent Protocol batch rollback has no completed project to restore")
    results = []
    for project_id in selected:
        project_state = state["projects"][project_id]
        project = plan_by_id[project_id]
        output = Path(project["output"]).resolve()
        result = {
            "project_id": project_id,
            "status": "failed",
            "source_version": project_state["source_version"],
            "target_version": project_state["target_version"],
            "failure": None,
            "evidence": project_state.get("evidence"),
        }
        try:
            if project_state["status"] == "rolled-back":
                current = snapshot_digest(
                    snapshot_files(output, [Path(value) for value in project["workspace_roots"]])
                )
                if current != project_state["baseline_digest"]:
                    raise BatchProjectError("rollback-post-drift", f"rolled-back project drifted: {project_id}")
                result["status"] = "skipped"
                results.append(result)
                continue
            if project_state["status"] not in {"completed", "skipped"}:
                raise BatchProjectError("rollback-project-not-complete", f"project is not rollback eligible: {project_id}")
            if not project_state.get("backup") or not Path(project_state["backup"]).is_file():
                raise BatchProjectError("rollback-backup-missing", f"rollback backup is missing: {project_id}")
            with _output_lock(output):
                current = snapshot_digest(
                    snapshot_files(output, [Path(value) for value in project["workspace_roots"]])
                )
                if current != project_state["applied_digest"]:
                    raise BatchProjectError(
                        "rollback-external-drift",
                        f"rollback refuses to overwrite managed bytes changed after batch apply: {project_id}",
                    )
                _restore_backup(Path(project_state["backup"]))
                restored = snapshot_digest(
                    snapshot_files(output, [Path(value) for value in project["workspace_roots"]])
                )
                if restored != project_state["baseline_digest"]:
                    raise BatchProjectError("rollback-verification-failed", f"rollback baseline digest mismatch: {project_id}")
                project_state["status"] = "rolled-back"
                project_state["failure"] = None
                evidence = _write_project_evidence(output, state["batch_id"], project_state, "rollback")
                project_state["evidence"] = str(evidence)
                _append_state_event(state, project_id, "rollback", "rolled-back")
                _save_state(state_path, state)
                _journal_batch_result(output, "rollback", "rolled-back", evidence)
                result["status"] = "passed"
                result["evidence"] = str(evidence)
        except BatchProjectError as exc:
            result["failure"] = {"category": exc.category, "detail": str(exc)}
            _append_state_event(state, project_id, "rollback", "failed", exc.category)
            _save_state(state_path, state)
        except (CkbError, OSError, ValueError, json.JSONDecodeError) as exc:
            result["failure"] = {"category": "rollback-failed", "detail": str(exc)}
            _append_state_event(state, project_id, "rollback", "failed", "rollback-failed")
            _save_state(state_path, state)
        results.append(result)
    state["status"] = _summarize_state(state)
    _save_state(state_path, state)
    failed = sum(item["status"] == "failed" for item in results)
    passed = sum(item["status"] == "passed" for item in results)
    return {
        "schema_version": BATCH_STATE_SCHEMA_VERSION,
        "batch_id": state["batch_id"],
        "status": "passed" if failed == 0 else "failed" if passed == 0 else "partial",
        "state": str(state_path),
        "summary": {"selected": len(results), "passed": passed, "skipped": len(results) - passed - failed, "failed": failed},
        "projects": results,
    }

def default_registry_path() -> Path:
    configured = os.environ.get("CKB_AUTOMATION_REGISTRY")
    return Path(configured).expanduser() if configured else Path.home() / ".ckb" / "automation-registry.json"

def _path_key(path: Path | str) -> str:
    value = os.path.abspath(os.path.expanduser(str(path)))
    value = os.path.normcase(os.path.normpath(value))
    return value.replace("\\", "/").rstrip("/")

def _is_within(path: Path | str, root: Path | str) -> bool:
    value = _path_key(path)
    base = _path_key(root)
    return value == base or value.startswith(base + "/")

def _read_registry(path: Path) -> dict[str, Any]:
    if not path.is_file():
        return {"schema_version": AUTOMATION_SCHEMA_VERSION, "projects": []}
    value = json_load(path)
    if value.get("schema_version") in {1, 2} and isinstance(value.get("projects"), list):
        # Earlier registries matched either the repository only or repository
        # plus workspace roots.  Read both through the current hard activation
        # contract; the next registry write upgrades the document atomically.
        value = {
            **value,
            "schema_version": AUTOMATION_SCHEMA_VERSION,
            "projects": [
                {
                    **item,
                    "workspace_roots": list(item.get("workspace_roots") or []),
                    "required_skill": REQUIRED_SKILL,
                    "require_skill_activation": True,
                }
                for item in value["projects"]
            ],
        }
    if value.get("schema_version") != AUTOMATION_SCHEMA_VERSION or not isinstance(value.get("projects"), list):
        raise CkbError(f"unsupported automation registry: {path}")
    for item in value["projects"]:
        item.setdefault("workspace_roots", [])
        item["required_skill"] = REQUIRED_SKILL
        item["require_skill_activation"] = True
    return value

def registry_status(registry_path: Path | None = None) -> dict[str, Any]:
    registry = (registry_path or default_registry_path()).expanduser().resolve()
    value = _read_registry(registry)
    return {
        "schema_version": AUTOMATION_SCHEMA_VERSION,
        "status": "ready",
        "registry": str(registry),
        "project_count": len(value["projects"]),
        "projects": value["projects"],
    }

def _registration_for_event(registry: Path, cwd: Path, harness: str) -> tuple[dict[str, Any], str, str] | None:
    candidates: list[tuple[int, int, dict[str, Any], str, str]] = []
    for item in _read_registry(registry)["projects"]:
        if not item.get("enabled", False) or harness not in item.get("harnesses", []):
            continue
        if _is_within(cwd, item["repo_root"]):
            root = str(item["repo_root"])
            candidates.append((2, len(_path_key(root)), item, "repository", root))
        for workspace_root in item.get("workspace_roots", []):
            if _is_within(cwd, workspace_root):
                candidates.append((1, len(_path_key(workspace_root)), item, "workspace", str(workspace_root)))
    if not candidates:
        return None
    best = max(candidates, key=lambda value: (value[0], value[1]))
    tied = [value for value in candidates if value[:2] == best[:2] and value[2]["registration_id"] != best[2]["registration_id"]]
    if tied:
        raise CkbError(f"automation event cwd matches multiple registrations at the same priority: {cwd}")
    return best[2], best[3], best[4]

def _event_path_text(value: str | Path, *, host_os: str | None = None) -> str:
    """Translate a harness path into the path syntax understood by this runtime.

    Codex Desktop can host ``app-server`` in WSL while a generated Hook invokes
    the bundled Windows Python through WSL interop.  The Hook payload then uses
    ``/mnt/<drive>/...`` even though ``pathlib`` in the receiving process expects
    a drive-letter path.  Normalize that boundary before registration matching
    and changed-path attribution; leave relative paths and native paths intact.
    """
    text = str(value).strip()
    if text.casefold().startswith("file:"):
        parsed = urlparse(text)
        if parsed.scheme.casefold() == "file":
            text = unquote(parsed.path)
            if parsed.netloc and parsed.netloc.casefold() != "localhost":
                text = f"//{parsed.netloc}{text}"
    target_os = os.name if host_os is None else host_os
    if target_os != "nt":
        return text
    normalized = text.replace("\\", "/")
    mounted = re.fullmatch(r"/mnt/([A-Za-z])(?:/(.*))?", normalized)
    if mounted:
        parts = [part for part in (mounted.group(2) or "").split("/") if part]
        return str(PureWindowsPath(f"{mounted.group(1).upper()}:\\", *parts))
    drive_uri = re.fullmatch(r"/([A-Za-z]):(?:/(.*))?", normalized)
    if drive_uri:
        parts = [part for part in (drive_uri.group(2) or "").split("/") if part]
        return str(PureWindowsPath(f"{drive_uri.group(1).upper()}:\\", *parts))
    return text

def _walk_values(value: Any) -> Iterator[tuple[str | None, Any]]:
    if isinstance(value, dict):
        for key, child in value.items():
            yield str(key), child
            yield from _walk_values(child)
    elif isinstance(value, list):
        for child in value:
            yield None, child
            yield from _walk_values(child)

def _first_scalar(value: Any, keys: set[str]) -> str | None:
    lowered = {key.casefold() for key in keys}
    if isinstance(value, dict):
        for key, child in value.items():
            if str(key).casefold() in lowered and isinstance(child, (str, int)):
                text = str(child).strip()
                if text:
                    return text
        for child in value.values():
            found = _first_scalar(child, keys)
            if found:
                return found
    elif isinstance(value, list):
        for child in value:
            found = _first_scalar(child, keys)
            if found:
                return found
    return None

def _text_content(value: Any) -> str:
    if isinstance(value, str):
        return value
    if isinstance(value, list):
        parts = [_text_content(item) for item in value]
        return "\n".join(item for item in parts if item)
    if isinstance(value, dict):
        direct = value.get("text")
        if isinstance(direct, str):
            return direct
        for key in ("content", "parts", "message", "delta", "info", "properties", "data"):
            if key in value:
                text = _text_content(value[key])
                if text:
                    return text
    return ""

def _event_name(raw: dict[str, Any]) -> str:
    for key in ("hook_event_name", "canonical_type", "event_type", "type"):
        value = raw.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip()
    event = raw.get("event")
    if isinstance(event, dict) and isinstance(event.get("type"), str):
        return event["type"]
    return "unknown"

def _normalized_skill_name(value: Any) -> str:
    text = str(value or "").strip().casefold()
    return text.removeprefix("[").removesuffix("]").lstrip("$/").strip()

def _skill_name(raw: dict[str, Any], tool_name: str | None = None, tool_input: Any = None) -> str | None:
    for key, value in _walk_values(raw):
        if not key or key.casefold() not in _SKILL_METADATA_KEYS:
            continue
        values = value if isinstance(value, list) else [value]
        for item in values:
            if isinstance(item, dict):
                item = item.get("name") or item.get("skill") or item.get("skill_name")
            if _normalized_skill_name(item) == REQUIRED_SKILL:
                return REQUIRED_SKILL
    if str(tool_name or "").casefold() == "skill" and isinstance(tool_input, dict):
        for key in ("skill", "name", "skill_name", "command"):
            if _normalized_skill_name(tool_input.get(key)) == REQUIRED_SKILL:
                return REQUIRED_SKILL
    prompt = str(raw.get("prompt") or raw.get("initial_prompt") or "")
    if _SKILL_PROMPT.search(prompt):
        return REQUIRED_SKILL
    return None

def _extract_paths(value: Any) -> list[str]:
    result: list[str] = []
    for key, child in _walk_values(value):
        if key and key.casefold() in _PATH_KEYS:
            if isinstance(child, str):
                result.append(child)
            elif isinstance(child, list):
                result.extend(str(item) for item in child if isinstance(item, (str, Path)))
        if isinstance(child, str):
            result.extend(match.strip() for match in _PATCH_PATH.findall(child))
    return list(dict.fromkeys(path.strip() for path in result if path.strip()))

def _redact_text(text: str, custom: list[re.Pattern[str]], max_chars: int) -> tuple[str, list[str]]:
    types: list[str] = []
    result = text
    for name, pattern in _DEFAULT_STRING_REDACTIONS:
        if pattern.search(result):
            types.append(name)
            if name == "credential-assignment":
                result = pattern.sub(lambda match: f"{match.group(1)}{match.group(2)}[REDACTED:CREDENTIAL]", result)
            else:
                result = pattern.sub(f"[REDACTED:{name.upper()}]", result)
    for index, pattern in enumerate(custom, 1):
        if pattern.search(result):
            types.append(f"custom-{index}")
            result = pattern.sub(f"[REDACTED:CUSTOM-{index}]", result)
    encoded = result.encode("utf-8")
    if len(encoded) > max_chars:
        data = encoded[:max_chars]
        while True:
            try:
                result = data.decode("utf-8") + f"\n[TRUNCATED:{len(encoded) - len(data)}-BYTES]"
                break
            except UnicodeDecodeError as exc:
                data = data[: exc.start]
        types.append("size-limit")
    return result, types

def redact_event(event: dict[str, Any], custom_patterns: list[str], max_chars: int) -> dict[str, Any]:
    custom = [re.compile(pattern) for pattern in custom_patterns]
    redaction_types: list[str] = []

    def redact(value: Any, key: str | None = None) -> Any:
        if key and _SENSITIVE_KEY.search(key) and value not in (None, ""):
            redaction_types.append("sensitive-key")
            return "[REDACTED:SENSITIVE-KEY]"
        if isinstance(value, str):
            text, types = _redact_text(value, custom, max_chars)
            redaction_types.extend(types)
            return text
        if isinstance(value, dict):
            return {str(child_key): redact(child, str(child_key)) for child_key, child in value.items()}
        if isinstance(value, list):
            return [redact(child) for child in value[:200]]
        if isinstance(value, (int, float, bool)) or value is None:
            return value
        return str(value)

    result = redact(event)
    result["redaction_count"] = len(redaction_types)
    result["redaction_types"] = sorted(set(redaction_types))
    return result

def redact(value: Any, key: str | None = None) -> Any:
        if key and _SENSITIVE_KEY.search(key) and value not in (None, ""):
            redaction_types.append("sensitive-key")
            return "[REDACTED:SENSITIVE-KEY]"
        if isinstance(value, str):
            text, types = _redact_text(value, custom, max_chars)
            redaction_types.extend(types)
            return text
        if isinstance(value, dict):
            return {str(child_key): redact(child, str(child_key)) for child_key, child in value.items()}
        if isinstance(value, list):
            return [redact(child) for child in value[:200]]
        if isinstance(value, (int, float, bool)) or value is None:
            return value
        return str(value)

def _automation_root(output: Path) -> Path:
    root = output / "workspace-meta" / "automation"
    for relative in ("spool/pending", "spool/processed", "spool/failed", "pending-reviews"):
        (root / relative).mkdir(parents=True, exist_ok=True)
    return root

def _git_status_paths(repo: Path) -> list[str]:
    prefix_result = run(["git", "rev-parse", "--show-prefix"], cwd=repo)
    prefix = prefix_result.stdout.strip().replace("\\", "/") if prefix_result.returncode == 0 else ""
    completed = run(["git", "status", "--porcelain=v1", "-z", "--untracked-files=all", "--", "."], cwd=repo)
    if completed.returncode:
        return []
    values: list[str] = []
    for record in completed.stdout.split("\0"):
        if len(record) < 4:
            continue
        path = record[3:].strip()
        if " -> " in path:
            path = path.rsplit(" -> ", 1)[1]
        if path:
            path = path.replace("\\", "/")
            if prefix and path.startswith(prefix):
                path = path[len(prefix) :]
            path = path.removeprefix("./")
            if path and _change_path_allowed(path):
                values.append(path)
    return sorted(set(values))

def _change_path_allowed(relative: str) -> bool:
    path = Path(relative.replace("\\", "/"))
    return not any(part.casefold() in _IGNORED_CHANGE_PARTS for part in path.parts) and path.suffix.casefold() not in _IGNORED_CHANGE_SUFFIXES
